import 'package:flutter/material.dart';import '../../domain/models/models.dart';class BalanceChart extends StatelessWidget{const BalanceChart({super.key,required this.points});final List<ForecastPoint> points;@override Widget build(BuildContext c)=>SizedBox(height:190,child:CustomPaint(painter:_P(points,Theme.of(c).colorScheme),child:const SizedBox.expand()));}class _P extends CustomPainter{_P(this.p,this.s);final List<ForecastPoint> p;final ColorScheme s;@override void paint(Canvas c,Size z){if(p.length<2)return;final min=p.map((x)=>x.balanceRials).reduce((a,b)=>a<b?a:b),max=p.map((x)=>x.balanceRials).reduce((a,b)=>a>b?a:b),span=(max-min).abs();final path=Path();for(var i=0;i<p.length;i++){final x=i/(p.length-1)*z.width;final y=span==0?z.height/2:z.height-(p[i].balanceRials-min)/span*z.height*.82-8;i==0?path.moveTo(x,y):path.lineTo(x,y);}c.drawPath(path,Paint()..color=s.primary..strokeWidth=3..style=PaintingStyle.stroke..strokeCap=StrokeCap.round);}@override bool shouldRepaint(covariant _P o)=>o.p!=p;}
